Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": { "name": "dataset" },
  "title": "Margen por Mes",
  "width": "container",
  "height": 400,
  "resolve": {
    "scale": { "y": "independent" }
  },
  "layer": [
    {
      "layer": [
        {
          "transform": [
            { "calculate": "datum.Ventas/1000", "as": "Ventas_k" }
          ],
          "mark": {
            "type": "area",
            "fill": "#66c2a5",
            "fillOpacity": 0.3,
            "stroke": "#2ca02c",
            "strokeWidth": 2,
            "line": true,
            "point": false
          },
          "encoding": {
            "x": {
              "field": "aaaa-mmm",
              "type": "ordinal",
              "title": null,
              "sort": false
            },
            "y": {
              "field": "Ventas_k",
              "type": "quantitative",
              "axis": {
                "title": "Miles de Dólares",
                "titleColor": "#333",
                "labelColor": "#555",
                "format": "$,.0f"
              }
            }
          }
        },
        {
          "transform": [
            { "calculate": "datum[''Costo de Ventas'']/1000", "as": "Costos_k" }
          ],
          "mark": {
            "type": "area",
            "fill": "#fc8d62",
            "fillOpacity": 0.3,
            "stroke": "#d62728",
            "strokeWidth": 2,
            "line": true,
            "point": false
          },
          "encoding": {
            "x": {
              "field": "aaaa-mmm",
              "type": "ordinal",
              "sort": false
            },
            "y": {
              "field": "Costos_k",
              "type": "quantitative"
            }
          }
        }
      ],
      "resolve": {
        "scale": { "y": "shared" }
      }
    },
    {
      "mark": {
        "type": "bar",
        "color": "#3182bd",
        "width": { "band": 0.6 },
        "tooltip": true
      },
      "encoding": {
        "x": {
          "field": "aaaa-mmm",
          "type": "ordinal",
          "title": null,
          "sort": false
        },
        "y": {
          "field": "% Margen de Ventas",
          "type": "quantitative",
          "axis": null,
          "scale": {
            "domain": [0, 1]
          }
        },
        "tooltip": [
          { "field": "aaaa-mmm", "type": "ordinal", "title": "Mes:" },
          { "field": "Ventas", "type": "quantitative", "title": "Ventas:", "format": "$,.0f" },
          { "field": "Costo de Ventas", "type": "quantitative", "title": "Costos:", "format": "$,.0f" },
          { "field": "% Margen de Ventas", "type": "quantitative", "title": "% Margen:", "format": ".0%" }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "dy": -8,
        "fontWeight": "bold",
        "fontSize": 12
      },
      "encoding": {
        "x": {
          "field": "aaaa-mmm",
          "type": "ordinal",
          "sort": false
        },
        "y": {
          "field": "% Margen de Ventas",
          "type": "quantitative"
        },
        "text": {
          "field": "% Margen de Ventas",
          "format": ".0%"
        },
        "color": {
          "condition": [
            {
              "test": "datum[''% Margen de Ventas''] > 0.35",
              "value": "#2ca02c"
            },
            {
              "test": "datum[''% Margen de Ventas''] < 0.10",
              "value": "#d62728"
            }
          ],
          "value": "black"
        }
      }
    }
  ]
}'
